import { describe, expect, it } from 'vitest';
import { makeInitialForm, productToApiPayload, productToForm } from '@/components/products/product-helpers';
import { buildImportPreview, type RawImportRow } from '@/components/products/import-parser';
import type { ProductRecord } from '@/components/products/types';

/** Product code (SKU) = permanent system ID: generated by the server, never sent by the form, never renamed by an import. */
describe('product code (SKU) in the form and the import preview', () => {
  const product = { id: 'p1', name: 'ปูน', sku: '2006893237927', priceLevel1: 150, unit: 'ถุง', barcode: '885123' } as ProductRecord;

  it('a new product form has no code (the server generates it on save)', () => {
    expect(makeInitialForm().sku).toBe('');
  });

  it('the edit form shows the stored code; the save payload never carries a SKU', () => {
    expect(productToForm(product).sku).toBe('2006893237927');
    const payload = productToApiPayload(product);
    expect('sku' in payload).toBe(false);
  });

  it('import preview: a different SKU in the file is a note, not a change, and the row keeps the product id', () => {
    const row = (r: Partial<RawImportRow>) => ({ 'ชื่อสินค้า': 'ปูน', 'ราคา 1': 150, 'หน่วยนับ': 'ถุง', ...r }) as RawImportRow;
    const [same, renamed, priced] = buildImportPreview([
      row({ 'รหัสสินค้า': '2006893237927' }),
      row({ 'รหัสระบบ (System ID - ห้ามแก้ไข)': 'p1', 'รหัสสินค้า': 'NEW-CODE' }),
      row({ 'รหัสระบบ (System ID - ห้ามแก้ไข)': 'p1', 'รหัสสินค้า': 'NEW-CODE', 'ราคา 1': 155 }),
    ], [product]);
    expect(same.changeType).toBe('UNCHANGED');
    expect(renamed).toMatchObject({ changeType: 'UNCHANGED', id: 'p1', isExisting: true });
    expect(renamed.diffs).toEqual(['SKU ในไฟล์ "NEW-CODE" ไม่ถูกใช้ (คงรหัสเดิม 2006893237927)']);
    expect(priced.changeType).toBe('CHANGED');
    expect(priced.diffs).toEqual(['ราคา 1: 150 ➔ 155', 'SKU ในไฟล์ "NEW-CODE" ไม่ถูกใช้ (คงรหัสเดิม 2006893237927)']);
  });
});
